package dev.hrai.jobposting.model;

import java.util.List;

/**
 * Full job posting: the model-generated {@link JobPostingDraft} plus
 * HR-supplied contact details. applicationEmail is never generated by the
 * model -- it comes straight from what HR typed, so it's never a guess.
 * HR reviews and edits this before posting it anywhere -- the agent never
 * publishes on its own.
 */
public record JobPosting(
        String title,
        String summary,
        List<String> mustHaveRequirements,
        List<String> preferredCriteria,
        List<String> educationRequirements,
        String employmentType,
        String location,
        String applicationEmail
) {
    public static JobPosting from(JobPostingDraft draft, String applicationEmail) {
        return new JobPosting(
                draft.title(), draft.summary(), draft.mustHaveRequirements(), draft.preferredCriteria(),
                draft.educationRequirements(), draft.employmentType(), draft.location(),
                applicationEmail == null || applicationEmail.isBlank() ? null : applicationEmail.trim()
        );
    }
}
